# -*- coding: utf-8 -*-
# Catechism bank — the ʿalāqa question sheet, items 48–70 (the istiʿāra by the early masters, al-Sakkākī and the Khaṭīb; the
# four kinds of majāz; the kināya).
ITEMS = [
 {"n": 48, "q": {"tr": "Selefe göre istiâre kaç kısımdır?", "en": "According to the early masters, how many kinds of istiʿāra are there?"},
  "a": {"tr": "Alâka ve karine ile mevzûun lehin gayrında kullanılmış lafız mânâsına mecazdan bir kısım olup alâkası müşâbehet olan istiâre, selef indinde musarraha ve mekniyye olur. Musarraha ayrıca müfrede, mürekkebe, asliyye ve tebeiyye olur.", "en": "The istiʿāra — a kind of majāz, a word used outside its coined sense by a relation and a clue, the relation being likeness — is for the early masters muṣarraḥa (declared) or makniyya (hidden). The declared is further single or compound, original or derived."},
  "ar": ["الِاسْتِعَارَةُ مُصَرَّحَةٌ وَمَكْنِيَّةٌ"], "notes": ["aqsam-al-istiara", "istiara-makniyya"]},
 {"n": 49, "q": {"tr": "Musarraha nedir?", "en": "What is the muṣarraḥa?"},
  "a": {"tr": "Müşebbehde kullanılmış, mezkûr müşebbehün bih lafzıdır; istiârede asıl olan müşebbehün bih mezkûr olduğu için musarraha denir. رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ: cesur adam şecâatte arslana teşbih edilmiş, cinsinden olduğu iddia olunmuş, أَسَد lafzı cesur adamda kullanılmış — istiâre-i musarraha-i asliyye. Müşebbeh: cesur adam; müşebbehün bih: arslan; vech-i şebeh: şecâat.", "en": "The word of the likened-to, stated and used for the likened; called «declared» because the likened-to, the root of the istiʿāra, is stated. رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ: the brave man is likened to the lion in courage, claimed to be of its kind, and أَسَد used for him — a declared, original istiʿāra. Likened: the brave man; likened-to: the lion; ground: courage."},
  "ar": ["لَفْظُ الْمُشَبَّهِ بِهِ الْمَذْكُورُ الْمُسْتَعْمَلُ فِي الْمُشَبَّهِ"], "notes": ["aqsam-al-istiara", "arkan-al-istiara"]},
 {"n": 50, "q": {"tr": "Mekniyye nedir?", "en": "What is the makniyya?"},
  "a": {"tr": "Müşebbehin yanında müşebbehün bihin lâzımını isbatla, müşebbehde kullanılmış gayr-i mezkûr müşebbehün bih lafzıdır; müşebbehün bih zikredilmeyip lâzımının zikriyle ona kinâye edildiği için mekniyye denir. أَظْفَارُ الْمَنِيَّةِ نَشِبَتْ بِفُلَانٍ: ölüm, fayda ile zararı ayırmaksızın helâk etmekte yırtıcıya teşbih edilmiş, سَبُع lafzı zikirden terk edilmiş ve lâzımı olan tırnaklar ölüme isbat edilmiştir — isbat edilen tırnaklara istiâre-i tahyîliyye denir ve selef indinde tahyîliyye mekniyye için lâzımdır.", "en": "The word of the likened-to, unstated and used for the likened, by affirming of the likened something that belongs to the likened-to; called «hidden» because the likened-to is not said but hinted at by its entailment. أَظْفَارُ الْمَنِيَّةِ نَشِبَتْ بِفُلَانٍ: death is likened to a beast of prey in destroying without telling benefit from harm, سَبُع is left unsaid, and its claws are affirmed of death — that affirming is the istiʿāra takhyīliyya, which for the early masters always accompanies the makniyya."},
  "ar": ["لَفْظُ الْمُشَبَّهِ بِهِ الْغَيْرُ الْمَذْكُورِ الْمُسْتَعْمَلُ فِي الْمُشَبَّهِ بِإِثْبَاتِ لَازِمِهِ عِنْدَهُ", "أَظْفَارُ الْمَنِيَّةِ نَشِبَتْ بِفُلَانٍ"], "notes": ["istiara-makniyya"]},
 {"n": 51, "q": {"tr": "Mezkûr lâzımın mecâz-ı lügavî olması câiz midir?", "en": "May the stated entailment itself be a majāz lughawī?"},
  "a": {"tr": "Selefe göre mezkûr lâzım (أَظْفَار) hakikat-i lügaviyyedir; tahyîliyye, bir şeyi mâ hüve lehin gayrına isbat mânâsına olan mecâz-ı aklîden bir kısımdır. Ancak Zemahşerî, müşebbeh için müşebbehün bihin râdifine benzer bir râdif olduğu zaman mezkûr lâzımın mecâz-ı lügavî olmasına cevaz vermiştir.", "en": "For the early masters the stated entailment (أَظْفَار) is a literal word, and the takhyīliyya is a kind of majāz ʿaqlī — affirming a thing of what it does not belong to. Al-Zamakhsharī, however, allowed the stated entailment to be a majāz lughawī when the likened has a concomitant resembling the likened-to's."},
  "ar": ["الْمَجَازُ الْعَقْلِيُّ"], "notes": ["istiara-makniyya", "majaz-aqli"]},
 {"n": 52, "q": {"tr": "يَنْقُضُونَ عَهْدَ اللهِ kavl-i şerifi neye misaldir?", "en": "What is يَنْقُضُونَ عَهْدَ اللهِ an example of?"},
  "a": {"tr": "Zemahşerî'ye göre iki mecaza: gayr-i mezkûr olan حَبْل (ip) veya binânın ahd mânâsında kullanılması istiâre-i mekniyye — ahd, matluba ulaştırmakta ipe teşbih edilmiş, حَبْل zikirden terk edilmiş, mülâyimi olan يَنْقُضُونَ ahde isbat edilmiştir; يَنْقُضُونَ'nun يُبْطِلُونَ mânâsında kullanılması istiâre-i musarraha-i tebeiyye — ibtal, bir şeyi hakikatinden çıkarmakta nakza teşbih edilmiştir.", "en": "For al-Zamakhsharī, two figures: the unstated rope or building used for the covenant is an istiʿāra makniyya — the covenant likened to a rope in reaching what is sought, حَبْل left unsaid, and its concomitant يَنْقُضُونَ affirmed of the covenant; and يَنْقُضُونَ used for يُبْطِلُونَ is a declared, derived istiʿāra — annulling likened to undoing a rope."},
  "ar": ["يَنْقُضُونَ عَهْدَ اللهِ"], "notes": ["istiara-makniyya", "istiara-tabaiyya"]},
 {"n": 53, "q": {"tr": "Musarraha-i müfrede nedir?", "en": "What is the single declared istiʿāra?"},
  "a": {"tr": "Müfred müşebbehde kullanılan mezkûr müfred müşebbehün bih lafzıdır: رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ'de müşebbeh ve müşebbehün bih müfred olduğu için.", "en": "The word of a single likened-to, stated and used for a single likened: as in رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ, where both are single."},
  "ar": ["لَفْظُ الْمُشَبَّهِ بِهِ الْمُفْرَدِ الْمَذْكُورُ الْمُسْتَعْمَلُ فِي الْمُشَبَّهِ الْمُفْرَدِ"], "notes": ["aqsam-al-istiara"]},
 {"n": 54, "q": {"tr": "Musarraha-i mürekkebe nedir?", "en": "What is the compound declared istiʿāra?"},
  "a": {"tr": "Mürekkeb müşebbehde kullanılan mezkûr mürekkeb müşebbehün bih lafzıdır; temsîliyye de denir. Fetvâda mütereddid için söylenen إِنِّي أَرَاكَ تُقَدِّمُ رِجْلًا وَتُؤَخِّرُ أُخْرَى gibi: ikdam ve ihcamda ikinci hey'et birinci hey'ete teşbih edilmiş, birinci hey'etin lafızları ikincide kullanılmıştır. Müşebbeh: fetvâda tereddüd eden müftü; müşebbehün bih: ayağını ileri geri atan adam; vech-i şebeh: kararsızlık.", "en": "The word of a compound likened-to, stated and used for a compound likened; also called tamthīliyya. As إِنِّي أَرَاكَ تُقَدِّمُ رِجْلًا وَتُؤَخِّرُ أُخْرَى said to one wavering over a fatwā: the second state is likened to the first in advancing and holding back, and the first's words are used for it. Likened: the wavering muftī; likened-to: a man stepping forward and back; ground: irresolution."},
  "ar": ["لَفْظُ الْمُشَبَّهِ بِهِ الْمُرَكَّبِ الْمَذْكُورُ الْمُسْتَعْمَلُ فِي الْمُشَبَّهِ الْمُرَكَّبِ", "إِنِّي أَرَاكَ تُقَدِّمُ رِجْلًا وَتُؤَخِّرُ أُخْرَى"], "notes": ["majaz-murakkab"]},
 {"n": 55, "q": {"tr": "Bazı muhakkıklara göre istiâre-i temsîliyye nedir?", "en": "What is the istiʿāra tamthīliyya according to some of the verifying scholars?"},
  "a": {"tr": "Onlara göre temsîliyyenin, mürekkeb müşebbehde kullanılmış müfred olması da câizdir: صَلَّيْتُ صَلَاةَ الْعِيدِ فِي الْمُقْمِرِ — güneşli gündüze yeşil otların karışmasından hâsıl olan hey'et, aydınlığın karanlıkla karışmasında mehtaplı geceye teşbih edilmiş ve مُقْمِر lafzı o hey'ette kullanılmıştır; karine, bayram namazının gündüz kılınmasıdır.", "en": "For them the tamthīliyya may also be a single word used for a compound likened: صَلَّيْتُ صَلَاةَ الْعِيدِ فِي الْمُقْمِرِ — the state of a sunlit day mingled with green meadows is likened to a moonlit night in light mixed with dark, and مُقْمِر is used for it; the clue is that the festival prayer is prayed by day."},
  "ar": ["صَلَّيْتُ صَلَاةَ الْعِيدِ فِي الْمُقْمِرِ"], "notes": ["majaz-murakkab"]},
 {"n": 56, "q": {"tr": "Mecâz-ı mürekkebler istiâre midir, mecâz-ı mürsel midir?", "en": "Are compound majāzes istiʿāra or majāz mursal?"},
  "a": {"tr": "Selefe göre mecâz-ı mürekkeb istiâreye mahsustur; fakat hak olan, istiâre olduğu gibi mecâz-ı mürsel de olmasıdır: lâzımı olan إِنِّي مُتَحَزِّنٌ mânâsında kullanılan هَوَايَ مَعَ الرَّكْبِ الْيَمَانِينَ مُصْعِدٌ gibi — alâka melzûmiyyet, karine şâirin hâlidir.", "en": "For the early masters the compound majāz belongs to the istiʿāra alone; but the truth is that it may be a majāz mursal too, as هَوَايَ مَعَ الرَّكْبِ الْيَمَانِينَ مُصْعِدٌ used for its entailment إِنِّي مُتَحَزِّنٌ — the relation malzūmiyya, the clue the poet's state."},
  "ar": ["هَوَايَ مَعَ الرَّكْبِ الْيَمَانِينَ مُصْعِدٌ"], "notes": ["majaz-murakkab", "majaz-mursal"]},
 {"n": 57, "q": {"tr": "İstiâre-i musarraha-i asliyye nedir?", "en": "What is the original declared istiʿāra?"},
  "a": {"tr": "İstiâre olunan lafız harf ve müştakın gayrı — cesur adamda kullanılan أَسَد gibi cins ismi, veya âlim-i mütebahhirde kullanılan أَبُو حَنِيفَة gibi alem — olursa istiâre-i musarraha-i asliyye olur.", "en": "When the borrowed word is neither a particle nor a derivative — a generic noun like أَسَد for the brave man, or a proper name like أَبُو حَنِيفَة for a deeply learned man — the declared istiʿāra is original."},
  "ar": ["الِاسْتِعَارَةُ الْأَصْلِيَّةُ"], "notes": ["istiara-tabaiyya"]},
 {"n": 58, "q": {"tr": "İstiâre-i musarraha-i tebeiyye nedir?", "en": "What is the derived declared istiʿāra?"},
  "a": {"tr": "İstiâre olunan lafız, دَلَّتْ mânâsına نَطَقَتْ gibi müştak veya بَاء mânâsına kullanılan فِي gibi harf olursa tebeiyye olur. نَطَقَتِ الْحَالُ: önce delâlet nutka teşbih edilmiş (asliyye), sonra masdara tebean نَطَقَتْ, دَلَّتْ mânâsında kullanılmıştır. عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ: sebebiyyet, mülâbesette zarfiyyete teşbih edilmiş; ona tebean فِي, بَاء-i sebebiyye mânâsında kullanılmıştır.", "en": "When the borrowed word is a derivative, like نَطَقَتْ for دَلَّتْ, or a particle, like فِي for the bāʾ. نَطَقَتِ الْحَالُ: first indicating is likened to speaking (the original), then, following the maṣdar, نَطَقَتْ is used for دَلَّتْ. عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ: causation is likened to containment in attachment, and following that فِي is used for the bāʾ of cause."},
  "ar": ["نَطَقَتِ الْحَالُ", "عُذِّبَتِ امْرَأَةٌ فِي هِرَّةٍ"], "notes": ["istiara-tabaiyya"]},
 {"n": 59, "q": {"tr": "İmam Sekkâkî'ye göre istiâre kaç kısımdır?", "en": "According to al-Sakkākī, how many kinds of istiʿāra are there?"},
  "a": {"tr": "Musarraha ve mekniyye; musarraha da tahkîkiyye ve tahyîliyye olur, ayrıca asliyye ve tebeiyye olur. Sekkâkî, tebeiyyenin karinesini mekniyye, tebeiyyeyi de mekniyyenin karinesi kılarak selef indindeki tebeiyyeyi mekniyye sûretine çevirmeyi tercih etmiştir: نَطَقَتِ الْحَالُ'de selefe göre نَطَقَتْ tebeiyye, حَال karinesidir; Sekkâkî'ye göre حَال mekniyye, نَطَقَتْ onun karinesi ve tahyîliyyedir.", "en": "Declared and hidden; the declared is realised (taḥqīqiyya) or imaginal (takhyīliyya), and original or derived. Al-Sakkākī chose to turn the early masters' derived istiʿāra into a hidden one, making the derived figure the clue of the hidden and the hidden the clue of the derived: in نَطَقَتِ الْحَالُ the early masters take نَطَقَتْ as derived and حَال as its clue; he takes حَال as hidden and نَطَقَتْ as its clue and an imaginal figure."},
  "ar": ["عِنْدَ السَّكَّاكِيِّ الِاسْتِعَارَةُ مُصَرَّحَةٌ وَمَكْنِيَّةٌ"], "notes": ["istiara-makniyya", "aqsam-al-istiara"]},
 {"n": 60, "q": {"tr": "İmam Sekkâkî'ye göre musarraha-i tahkîkiyye nedir?", "en": "According to al-Sakkākī, what is the realised declared istiʿāra?"},
  "a": {"tr": "Murad olunan mânâ hissen veya aklen tahakkuk ederse musarraha tahkîkiyye olur. Hissen: cesur adamda kullanılan أَسَد. Aklen: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ — din, matluba ulaştırmakta yola teşbih edilmiş, صِرَاط dinde kullanılmıştır; müşebbeh din, müşebbehün bih yol, vech-i şebeh matluba ulaştırmaktır.", "en": "When the meaning intended is realised by sense or by reason. By sense: أَسَد for the brave man. By reason: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ — religion likened to a road in leading to what is sought, and صِرَاط used for it; likened the religion, likened-to the road, ground leading to the goal."},
  "ar": ["اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ"], "notes": ["arkan-al-istiara", "aqsam-al-istiara"]},
 {"n": 61, "q": {"tr": "İmam Sekkâkî'ye göre musarraha-i tahyîliyye nedir?", "en": "According to al-Sakkākī, what is the imaginal declared istiʿāra?"},
  "a": {"tr": "Murad olunan mânâ hissen ve aklen tahakkuk etmeyip vehmî bir sûret olursa tahyîliyyedir: أَظْفَارُ الْمَنِيَّةِ'deki أَظْفَار — vehim ölüme arslan sûreti verip ona tırnaklar isbat eder; bu tırnaklar his ve akılda değil hayalde mevcuttur. Selefe göre أَظْفَار hakikat, Sekkâkî'ye göre istiâre-i musarraha-i tahyîliyyedir: hayalî tırnaklar hakikî tırnaklara teşbih edilmiş, أَظْفَار lafzı hayalî tırnaklarda kullanılmıştır.", "en": "When the meaning intended is realised neither by sense nor by reason but is a fancied form: أَظْفَار in أَظْفَارُ الْمَنِيَّةِ — fancy gives death a lion's shape and affirms claws of it, which exist only in the imagination. For the early masters أَظْفَار is literal; for al-Sakkākī it is an imaginal declared istiʿāra: fancied claws likened to real ones, and أَظْفَار used for the fancied."},
  "ar": ["أَظْفَارُ الْمَنِيَّةِ"], "notes": ["istiara-makniyya"]},
 {"n": 62, "q": {"tr": "İmam Sekkâkî'ye göre mekniyye nedir?", "en": "According to al-Sakkākī, what is the makniyya?"},
  "a": {"tr": "Müşebbehün bihde kullanılmış müşebbeh lafzıdır. أَظْفَارُ الْمَنِيَّةِ نَشِبَتْ بِفُلَانٍ'de ölüm yırtıcıya teşbih edilmiş, aynı olduğu iddia olunmuş; yırtıcı için biri müteâref biri gayr-i müteâref iki fert hâsıl olmuş, مَنِيَّة lafzı gayr-i müteâref fertte (iddiâî sebu'da) kullanılmıştır. Selefe göre mekniyye سَبُع'un ölümde, Sekkâkî'ye göre مَنِيَّة'nin sebu'da kullanılmasıdır.", "en": "The word of the likened, used for the likened-to. In أَظْفَارُ الْمَنِيَّةِ نَشِبَتْ بِفُلَانٍ death is likened to the beast and claimed to be one with it; the beast gains two members, one familiar and one not, and مَنِيَّة is used for the unfamiliar member. For the early masters the makniyya is سَبُع used for death; for al-Sakkākī it is مَنِيَّة used for the beast."},
  "ar": ["لَفْظُ الْمُشَبَّهِ الْمُسْتَعْمَلُ فِي الْمُشَبَّهِ بِهِ"], "notes": ["istiara-makniyya"]},
 {"n": 63, "q": {"tr": "Hatîb-i Dımaşkî'ye göre istiâre kaç kısımdır?", "en": "According to the Khaṭīb of Damascus, how many kinds of istiʿāra are there?"},
  "a": {"tr": "Mezkûr mânâsıyla istiâre yalnız musarrahadır — müfrede, mürekkebe, asliyye, tebeiyye olarak; fakat üzerine istiâre lafzı ıtlak olunan şey mânâsıyla üç kısımdır: musarraha, mekniyye ve tahyîliyye.", "en": "In its stated sense the istiʿāra is only the declared — single, compound, original, derived; but in the sense of what the word «istiʿāra» is applied to, it is three: declared, hidden and imaginal."},
  "ar": ["الِاسْتِعَارَةُ عِنْدَ الْخَطِيبِ"], "notes": ["istiara-makniyya"]},
 {"n": 64, "q": {"tr": "Hatîb-i Dımaşkî'ye göre mekniyye nedir?", "en": "According to the Khaṭīb of Damascus, what is the makniyya?"},
  "a": {"tr": "Nefiste gizli olan teşbihe delâlet etmesi için müşebbehün bihin lâzımını müşebbehe isbatla beraber, nefiste bir şeyi bir şeye teşbih etmektir. Tahyîliyye ise müşebbehün bihin lâzımını müşebbehe isbattır.", "en": "Likening one thing to another in the mind, together with affirming of the likened something that belongs to the likened-to, so as to signal the likening hidden in the mind. The takhyīliyya is that affirming itself."},
  "ar": ["تَشْبِيهُ شَيْءٍ بِشَيْءٍ فِي النَّفْسِ مَعَ إِثْبَاتِ لَازِمِ الْمُشَبَّهِ بِهِ لِلْمُشَبَّهِ لِلدَّلَالَةِ عَلَى ذَلِكَ التَّشْبِيهِ الْمُضْمَرِ فِي النَّفْسِ"], "notes": ["istiara-makniyya"]},
 {"n": 65, "q": {"tr": "Mutlak mecaz kaç kısımdır?", "en": "How many kinds has the majāz absolutely?"},
  "a": {"tr": "Dört: mecâz-ı lügavî, mecâz-ı aklî, mecaz bi'z-ziyâde, mecaz bi'n-nuksan. Mecâz-ı lügavî, kitabın başında geçtiği gibi alâka ve karine ile mevzûun lehin gayrında kullanılan lafızdır; son ikisine i'rabda mecaz da denir.", "en": "Four: the majāz of the word, the majāz of attribution, the majāz by addition and the majāz by omission. The first is the word used outside its coined sense by relation and clue, as at the book's opening; the last two are also called majāz in the iʿrāb."},
  "ar": ["الْمَجَازُ اللُّغَوِيُّ وَالْمَجَازُ الْعَقْلِيُّ وَالْمَجَازُ بِالزِّيَادَةِ وَالْمَجَازُ بِالنُّقْصَانِ"], "notes": ["anwa-al-majaz"]},
 {"n": 66, "q": {"tr": "Mecâz-ı aklî nedir?", "en": "What is the majāz ʿaqlī?"},
  "a": {"tr": "Mütekellimin zâhirî hâlinde bir şeyi, mâ hüve lehin gayrına nisbet etmektir: أَنْبَتَ الرَّبِيعُ الْبَقْلَ — bitirmenin ilkbahara isnadı mümine göre mecâz-ı aklîdir, bitiren Allah'tır, bahar bitirmenin vaktidir; هَزَمَ الْأَمِيرُ الْجُنْدَ — hezimeti yapan emîrin askerleridir.", "en": "Attributing a thing, in the speaker's apparent state, to what it does not belong to: أَنْبَتَ الرَّبِيعُ الْبَقْلَ — the growing attributed to spring is, for the believer, a majāz of attribution, since God makes things grow and spring is its time; هَزَمَ الْأَمِيرُ الْجُنْدَ — the rout is his soldiers' doing."},
  "ar": ["نِسْبَةُ الشَّيْءِ إِلَى غَيْرِ مَا هُوَ لَهُ فِي ظَاهِرِ حَالِ الْمُتَكَلِّمِ", "أَنْبَتَ الرَّبِيعُ الْبَقْلَ"], "notes": ["majaz-aqli"]},
 {"n": 67, "q": {"tr": "Mecaz bi'z-ziyâde nedir?", "en": "What is the majāz by addition?"},
  "a": {"tr": "Murad üzerine zâid bir şeyin ziyâdesiyle i'rabı değişen lafızdır: لَيْسَ كَمِثْلِهِ شَيْءٌ — مِثْل'in nasb i'rabı kâfın ziyâdesiyle cerre değişmiştir.", "en": "A word whose iʿrāb has changed by the addition of something beyond what is meant: لَيْسَ كَمِثْلِهِ شَيْءٌ — the naṣb of مِثْل changed to jarr by the added kāf."},
  "ar": ["لَفْظٌ تَغَيَّرَ إِعْرَابُهُ بِشَيْءٍ زَائِدٍ عَلَى الْمُرَادِ", "لَيْسَ كَمِثْلِهِ شَيْءٌ"], "notes": ["majaz-ziyada-nuqsan"]},
 {"n": 68, "q": {"tr": "Mecaz bi'n-nuksan nedir?", "en": "What is the majāz by omission?"},
  "a": {"tr": "Lafızdaki bir noksanlık sebebiyle i'rabı değişen lafızdır: وَاسْأَلِ الْقَرْيَةَ — muzâf olan أَهْل'in hazfiyle الْقَرْيَة'nin cer i'rabı nasba değişmiştir.", "en": "A word whose iʿrāb has changed by something dropped from the wording: وَاسْأَلِ الْقَرْيَةَ — with the annexed أَهْل dropped, the jarr of الْقَرْيَة became naṣb."},
  "ar": ["لَفْظٌ تَغَيَّرَ إِعْرَابُهُ بِنُقْصَانٍ فِي اللَّفْظِ", "وَاسْأَلِ الْقَرْيَةَ"], "notes": ["majaz-ziyada-nuqsan"]},
 {"n": 69, "q": {"tr": "Kinâyede bulunan iki şey nedir?", "en": "What are the two things found in a kināya?"},
  "a": {"tr": "Meknî bih: kinevî mânâda kullanılan lafız. Meknî anh: kendisinden kinâye olunan şey. فُلَانٌ طَوِيلُ النِّجَادِ'de meknî bih طَوِيلُ النِّجَادِ, meknî anh boy uzunluğudur.", "en": "The maknī bih — the word used in the hinted sense; and the maknī ʿanhu — the thing hinted at. In فُلَانٌ طَوِيلُ النِّجَادِ the former is طَوِيلُ النِّجَادِ, the latter tallness."},
  "ar": ["الْمَكْنِيُّ بِهِ وَالْمَكْنِيُّ عَنْهُ"], "notes": ["kinaya", "aqsam-al-kinaya"]},
 {"n": 70, "q": {"tr": "Meknî anh itibariyle kinâye kaç kısımdır?", "en": "By the thing hinted at, how many kinds of kināya are there?"},
  "a": {"tr": "Üç: meknî anh zat olur — طَعَنَ فُلَانٌ مَجْمَعَ ضِغْنِكَ (meknî anh kalptir); sıfat olur — فُلَانٌ طَوِيلُ النِّجَادِ (boy uzunluğu); zat ile sıfat arasında nisbet olur — إِنَّ الْكَرَمَ فِي بَيْتِ فُلَانٍ (cömertliğin falanda olması).", "en": "Three: the thing hinted at is an essence — طَعَنَ فُلَانٌ مَجْمَعَ ضِغْنِكَ (the heart); a quality — فُلَانٌ طَوِيلُ النِّجَادِ (tallness); or an attribution of a quality to an essence — إِنَّ الْكَرَمَ فِي بَيْتِ فُلَانٍ (that generosity is his)."},
  "ar": ["إِنَّ الْكَرَمَ فِي بَيْتِ فُلَانٍ", "طَعَنَ فُلَانٌ مَجْمَعَ ضِغْنِكَ"], "notes": ["aqsam-al-kinaya"]},
]
